def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def pos(value, default=(0, 0)):
        if isinstance(value, (list, tuple)) and len(value) >= 2:
            return value[0], value[1]
        return default

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def step_toward(src, dst):
        return [clamp_step(dst[0] - src[0]), clamp_step(dst[1] - src[1])]

    def step_away(src, dst):
        return [clamp_step(src[0] - dst[0]), clamp_step(src[1] - dst[1])]

    def best_of(points, src, prefer_far=False):
        best = None
        best_score = None
        for p in points:
            if not isinstance(p, (list, tuple)) or len(p) < 2:
                continue
            p = (p[0], p[1])
            score = manhattan(src, p)
            if best is None:
                best, best_score = p, score
            else:
                if prefer_far:
                    if score > best_score:
                        best, best_score = p, score
                else:
                    if score < best_score:
                        best, best_score = p, score
        return best

    env = observation.get("environment_name", "")
    if not env:
        if observation.get("resources") is not None:
            env = "resource_collection"
        elif observation.get("unclaimed_cells") is not None or observation.get("opponent_territory") is not None:
            env = "territory_control"
        else:
            env = "pursuit_evasion"

    sx, sy = pos(observation.get("self_position"))
    ox, oy = pos(observation.get("opponent_position"), (sx, sy))
    self_pos = (sx, sy)
    opp_pos = (ox, oy)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward(self_pos, opp_pos)
        corners = [
            (0, 0),
            (0, observation.get("grid_height", 1) - 1),
            (observation.get("grid_width", 1) - 1, 0),
            (observation.get("grid_width", 1) - 1, observation.get("grid_height", 1) - 1),
        ]
        target = best_of(corners, opp_pos, prefer_far=True)
        return step_toward(self_pos, target) if target else step_away(self_pos, opp_pos)

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or []
        if targets:
            # Prefer nearer target, but if opponent is closer to it, pick another.
            chosen = None
            chosen_score = None
            for t in targets:
                if not isinstance(t, (list, tuple)) or len(t) < 2:
                    continue
                t = (t[0], t[1])
                score = manhattan(self_pos, t)
                opp_score = manhattan(opp_pos, t)
                value = score + (1 if opp_score <= score else 0)
                if chosen is None or value < chosen_score:
                    chosen, chosen_score = t, value
            if chosen is not None:
                return step_toward(self_pos, chosen)
        # Fallback: pressure opponent or hold.
        return step_toward(self_pos, opp_pos)

    resources = observation.get("resources") or observation.get("resource_cells") or []
    if resources:
        target = best_of(resources, self_pos, prefer_far=False)
        if target is not None:
            return step_toward(self_pos, target)

    # General fallback: if ahead/near opponent, move toward; otherwise move toward center.
    gw = observation.get("grid_width", 0)
    gh = observation.get("grid_height", 0)
    if gw and gh:
